// Helper functions

func getBadge(stats *types.StatsData, key string) int {
	if stats == nil {
		return 0
	}
	switch key {
	case "containers":
		return stats.ContainersRunning
	case "security":
		return stats.SecurityIssues
	case "updates":
		return stats.UpdatesAvailable
	default:
		return 0
	}
}

func getUserInitial(user *types.UserData) string {
	if user == nil || user.Username == "" {
		return "?"
	}
	return string([]rune(user.Username)[0])
}

func getUserName(user *types.UserData) string {
	if user == nil {
		return "Unknown"
	}
	return user.Username
}

func getUserRole(user *types.UserData) string {
	if user == nil {
		return ""
	}
	return user.Role
}

func itoa(n int) string {
	return fmt.Sprintf("%d", n)
}

// iconClass returns the Font Awesome class string for an icon name.
// Bare names ("fa-server") get the default "fas " (solid) prefix to
// preserve the original navItem shape. Names that already include a
// family prefix ("fab fa-docker", "far fa-clock", etc.) are returned
// as-is so brand and other-family glyphs render correctly.
func iconClass(name string) string {
	if strings.HasPrefix(name, "fas ") || strings.HasPrefix(name, "fab ") ||
		strings.HasPrefix(name, "far ") || strings.HasPrefix(name, "fal ") ||
		strings.HasPrefix(name, "fad ") {
		return name
	}
	return "fas " + name
}

